/* Differential-test harness: runs lifted functions on cases generated by
 * tools/difftest.py and reports final registers + CRCs of memory regions.
 *
 * usage: harness image.bin cases.bin results.bin
 */
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include "rt.h"

uint8_t *G;

typedef struct { uint32_t addr; void (*fn)(CPU *); } FuncEnt;
extern const FuncEnt FUNCS[];
extern const int NFUNCS;

static uint32_t crc_table[256];
static void crc_init(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++) c = (c & 1) ? 0xEDB88320u ^ (c >> 1) : c >> 1;
        crc_table[i] = c;
    }
}
static uint32_t crc32_update(uint32_t crc, const uint8_t *p, size_t n) {
    crc = ~crc;
    while (n--) crc = crc_table[(crc ^ *p++) & 0xff] ^ (crc >> 8);
    return ~crc;
}

static void rd(FILE *f, void *p, size_t n) {
    if (fread(p, 1, n, f) != n) { fprintf(stderr, "short read\n"); exit(2); }
}

#include <setjmp.h>
static jmp_buf bad_jmp;
void rt_bad_indirect(CPU *c, uint32_t t) {   /* case reaches code that is not lifted: skip it */
    (void)c; (void)t; longjmp(bad_jmp, 1);
}

int main(int argc, char **argv) {
    if (argc < 4) { fprintf(stderr, "usage: harness image cases results\n"); return 2; }
    crc_init();
    G = mmap(NULL, 1ull << 32, PROT_READ | PROT_WRITE,
             MAP_PRIVATE | MAP_ANON | MAP_NORESERVE, -1, 0);
    if (G == MAP_FAILED) { perror("mmap"); return 2; }

    FILE *fi = fopen(argv[1], "rb"), *fc = fopen(argv[2], "rb"), *fo = fopen(argv[3], "wb");
    FILE *fh = getenv("DUMP_HEAP") ? fopen("build/results.heap", "wb") : NULL;
    if (!fi || !fc || !fo) { perror("open"); return 2; }

    uint32_t hdr[3];                       /* img_base, img_size, n_writable */
    rd(fc, hdr, sizeof hdr);
    uint32_t img_base = hdr[0], img_size = hdr[1], nwr = hdr[2];
    uint8_t *pristine = malloc(img_size);
    rd(fi, pristine, img_size);
    memcpy(G + img_base, pristine, img_size);
    uint32_t wr[64][2];
    rd(fc, wr, nwr * 8);
    uint32_t mem[5];                       /* heap_base, heap_size, stack_base, stack_size, ncases */
    rd(fc, mem, sizeof mem);
    uint8_t *heap_init = malloc(mem[1]), *stack_init = malloc(mem[3]);

    for (uint32_t n = 0; n < mem[4]; n++) {
        uint32_t fa, regs[8];
        CPU c;
        memset(&c, 0, sizeof c);
        rd(fc, &fa, 4);
        rd(fc, regs, 32);
        rd(fc, c.xmm, sizeof c.xmm);
        uint32_t nfpu; uint64_t fv[4];
        rd(fc, &nfpu, 4);
        rd(fc, fv, sizeof fv);
        c.fcw = 0x27F;
        {   static const double STALE[8] = { 1.5, -2.25, 3.125, 100.0, -0.5, 7.0, 0.1, 42.0 };
            for (int k = 0; k < 8; k++) c.fst[7 - k] = STALE[k]; }
        for (uint32_t k = 0; k < nfpu; k++) { c.ftop = (c.ftop - 1) & 7; memcpy(&c.fst[c.ftop], &fv[k], 8); }
        rd(fc, G + mem[0], mem[1]);
        rd(fc, G + mem[2], mem[3]);
        for (uint32_t i = 0; i < nwr; i++)
            memcpy(G + wr[i][0], pristine + (wr[i][0] - img_base), wr[i][1] - wr[i][0]);
        void (*fn)(CPU *) = NULL;
        for (int i = 0; i < NFUNCS; i++) if (FUNCS[i].addr == fa) { fn = FUNCS[i].fn; break; }
        if (!fn) { fprintf(stderr, "function %x not lifted\n", fa); return 2; }
        c.eax = regs[0]; c.ecx = regs[1]; c.edx = regs[2]; c.ebx = regs[3];
        c.esp = regs[4]; c.ebp = regs[5]; c.esi = regs[6]; c.edi = regs[7];
        if (setjmp(bad_jmp)) {
            uint32_t out[60] = { 0xBAD1BAD1u, 0xBAD2BAD2u };
            fwrite(out, 4, 60, fo);
            if (fh) fwrite(G + mem[0], 1, mem[1], fh);
            continue;
        }
        fn(&c);
        uint32_t out[60] = { c.eax, c.ecx, c.edx, c.ebx, c.esp, c.ebp, c.esi, c.edi };
        out[8] = crc32_update(0, G + mem[0], mem[1]);
        out[9] = crc32_update(0, G + mem[2], mem[3]);
        uint32_t w = 0;
        for (uint32_t i = 0; i < nwr; i++) w = crc32_update(w, G + wr[i][0], wr[i][1] - wr[i][0]);
        out[10] = w;
        memcpy(out + 11, c.xmm, sizeof c.xmm);
        out[43] = c.ftop;
        for (int i = 0; i < 8; i++) memcpy(out + 44 + 2 * i, &c.fst[(c.ftop + i) & 7], 8);
        fwrite(out, 4, 60, fo);
        if (fh) fwrite(G + mem[0], 1, mem[1], fh);
    }
    fclose(fo);
    return 0;
}
